$('#plugin-detail').addEventListener('click',async(event)=>{
  const button=event.target.closest('[data-plugin-action]'),plugin=selectedManagedPlugin();if(!button||!plugin)return;
  const action=button.dataset.pluginAction;button.disabled=true;
  try{
    if(action==='prepare'||action==='setup'){
      button.textContent=action==='prepare'?'Installing and preparing…':'Preparing setup…';startPluginProgressUpdates();
      try{pluginManagerPlugins=action==='prepare'?await window.pigeon.preparePlugin(plugin.id):await window.pigeon.setupPlugin(plugin.id);showToast(`${plugin.name} model is downloaded and ready`);}finally{stopPluginProgressUpdates();}
    }
    if(action==='cancel-setup')pluginManagerPlugins=await window.pigeon.cancelPluginSetup(plugin.id);
    if(action==='toggle'){if(!plugin.enabled)startPluginProgressUpdates();try{pluginManagerPlugins=await window.pigeon.setPluginEnabled(plugin.id,!plugin.enabled);showToast(plugin.enabled?`${plugin.name} disabled`:`${plugin.name} is running locally`);}finally{stopPluginProgressUpdates();}}
    if(action==='health'){const health=await window.pigeon.checkPluginHealth(plugin.id);showToast(health.ok?health.detail:`Service check failed · ${health.detail}`);pluginManagerPlugins=await window.pigeon.listPlugins();}
    if(action==='import-model'){pluginManagerPlugins=await window.pigeon.importPluginModel(plugin.id);showToast('Model selected. Choose Validate imported model to complete setup.');}
    if(action==='remove-model'&&await requestConfirmation({title:'Remove Managed Model',message:'Remove the downloaded Simple LaMa model and any partial download? The plugin configuration and private Python runtime will be retained.',confirmText:'Remove Model'}))pluginManagerPlugins=await window.pigeon.removePluginModel(plugin.id);
    if(action==='open-files')await window.pigeon.openPluginsFolder(plugin.id);
    if(action==='save-config'){const config=Object.fromEntries([...$('#plugin-detail').querySelectorAll('[data-plugin-config]')].map((input)=>[input.dataset.pluginConfig,input.type==='number'?Number(input.value):input.value]));pluginManagerPlugins=await window.pigeon.configurePlugin(plugin.id,config);showToast(`${plugin.name} configuration saved`);}
    if(action==='run'){const result=await window.pigeon.runPlugin(plugin.entry);showToast(result.error||`${plugin.name} completed`);}
    if(action==='uninstall'&&await requestConfirmation({title:'Uninstall Plugin',message:`Uninstall “${plugin.name}” and remove its managed runtime, model, and plugin files?`,confirmText:'Uninstall'}))pluginManagerPlugins=await window.pigeon.uninstallPlugin(plugin.id);
    renderPluginManager();
  }catch(error){showToast(error.message);await refreshPluginManager();}finally{button.disabled=false;}
});
